import java.io.*;
import java.util.*;

public class Main {
    static int minutes(String t) {
        return Integer.parseInt(t.substring(0, 2)) * 60 + Integer.parseInt(t.substring(3));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        int[] t = new int[n];
        for (int i = 0; i < n; i++) t[i] = minutes(st.nextToken());
        int current = minutes(st.nextToken()), last = -1;
        for (int m : t) if (m < current) last = Math.max(last, m); // a bus leaving right now has not departed
        System.out.println(last >= 0 ? current - last : -1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func minutes(t string) int {
	h, _ := strconv.Atoi(t[:2])
	m, _ := strconv.Atoi(t[3:])
	return h*60 + m
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	t := make([]int, n)
	for i := range t {
		var s string
		fmt.Fscan(in, &s)
		t[i] = minutes(s)
	}
	var s string
	fmt.Fscan(in, &s)
	current, last := minutes(s), -1
	for _, m := range t {
		if m < current { // a bus leaving right now has not departed
			last = max(last, m)
		}
	}
	if last >= 0 {
		fmt.Println(current - last)
	} else {
		fmt.Println(-1)
	}
}
